additionalExercises.referenceSolution:
#include <stdio.h>

typedef struct node {
    int value;
    struct node *next;
} Node;

int main(void) {
    Node nodes[1000];
    int n;
    scanf("%d", &n);
    for (int i = 0; i < n; i++) {
        scanf("%d", &nodes[i].value);
    }
    for (int i = 0; i < n; i++) {
        int j;
        scanf("%d", &j);
        nodes[i].next = (j == -1) ? NULL : &nodes[j];
    }
    int start;
    scanf("%d", &start);
    int length = 0;
    long long sum = 0;
    for (const Node *p = &nodes[start]; p != NULL; p = p->next) {
        printf(length > 0 ? " %d" : "%d", p->value);
        length++;
        sum += p->value;
    }
    printf("\n%d %lld\n", length, sum);
    return 0;
}

